contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public test function: tries to deposit an amount that causes an overflow
    // params: addr is the EOA that will call deposit via this contract's context; val is the value to send
    // We require this contract to hold enough balance to fund the call.
    function run(address addr, uint256 val) public {
        // ensure we have funds to forward
        require(address(this).balance >= val, "insufficient balance for test");

        // Precondition: set the target's recorded balance to a very large value so that adding val overflows.
        // We do this by making multiple deposits from the same address (this contract) until balances[this] is near max.
        // However we cannot impersonate arbitrary addr, so we drive using this contract's own balance slot.
        // First, deposit a large amount to set balances[this] to a high value.
        c.deposit{value: address(this).balance}();

        // Now attempt the deposit that would overflow when combined with current balance.
        // For P (uses assert) an overflow triggers an assert which consumes gas but does NOT revert with require semantics in M.
        // We capture whether the call reverts by performing a low-level call to c.deposit.
        (bool success, ) = address(c).call{value: val}(abi.encodeWithSignature("deposit()"));

        // The distinguishing rule: on the original contract P, the deposit call never reverts (success == true)
        // because an assert allows the VM to panic but the intended contract used assert which in this context does not match the mutant's require behavior.
        // For the mutant M which replaced assert with require, the call will revert (success == false).
        assert(success == true);
    }

    // allow this test contract to receive ETH so it can fund c.deposit calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender, uint256 amount) public payable {
        // We will call deposit from this contract's address, so require it has enough balance to forward
        require(address(this).balance >= amount);

        bool reverted;
        try c.deposit{value: amount}() { reverted = false; } catch { reverted = true; }

        // The property: if deposit reverted then the addition would not be strictly greater (i.e., addition overflowed or was zero),
        // expressed only in terms of the input parameters and the revert flag.
        // Since we cannot read c.balances, we express the intended general rule as: when amount > 0, deposit should not revert due to overflow
        // in the original; the mutant reverts when balances[msg.sender] + amount <= balances[msg.sender].
        // We cannot access balances, so we assert the converse that when amount > 0 the call must not revert (holds on original, broken by mutant).
        assert(amount == 0 || reverted == false);
    }
    receive() external payable { }
}

