contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: make an initial deposit (maybe zero), then make another deposit of amount > 0.
    // Assert that the stored balance for this contract's address strictly increases after a positive-value deposit.
    function runTest(uint256 firstAmount, uint256 secondAmount) public payable {
        // ensure we have enough ETH in this contract to forward the calls
        require(address(this).balance >= firstAmount + secondAmount, "insufficient balance for test");
        // make first deposit
        c.deposit{value: firstAmount}();
        // read recorded balance after first deposit
        uint256 bal1 = c.balances(address(this));
        // require secondAmount > 0 to target the behavior change
        require(secondAmount > 0, "second deposit must be positive");
        // make second deposit
        c.deposit{value: secondAmount}();
        // read recorded balance after second deposit
        uint256 bal2 = c.balances(address(this));
        // The original contract P used an assert preventing zero-value deposits from being accepted
        // and ensuring that any positive deposit increases the stored balance strictly.
        // The mutant removed that check, allowing a case where a positive-value deposit may not increase
        // the stored balance (e.g., due to overflow being unchecked). We assert the property that
        // a positive deposit strictly increases the recorded balance.
        assert(bal2 > bal1);
    }

    // Allow the test contract to receive ETH so tests can supply funds
    receive() external payable {}
}

