pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzz parameters: actor (address) and amount (uint256)
    function testFuzz_property(address actor, uint256 amount) public {
        // admissible domain: actor must be a nonzero address and amount bounded reasonably to avoid OOG
        vm.assume(actor != address(0));
        // bound amount to a reasonable range that the fuzzer can explore and that allows sending value
        amount = bound(amount, 0, 1 ether);

        // record balance before
        // use address(c).balance only for contract total, but we need depositor's recorded balance via public getter
        // The reference contract has mapping balances (not declared public), so we cannot read it directly.
        // However, we can observe behavior by calling deposit and then using withdraw to check consistency.
        // Strategy: For any positive deposit amount, after deposit, withdrawing that amount must succeed (i.e., not revert)
        // and contract should transfer the funds, so the caller can retrieve the amount. The mutant accepting zero-value
        // deposits may allow a zero deposit that does not change recorded balances, so attempting to withdraw a positive
        // amount previously only "deposited" as zero would revert. To make this observable we do:
        // 1) fund actor externally
        // 2) actor deposits 'amount'
        // 3) If amount > 0 then withdraw(amount) must succeed (i.e., not revert). This is the universal property.

        vm.deal(actor, amount);
        bool depositOk;
        // perform deposit as actor
        vm.prank(actor);
        try c.deposit{value: amount}() {
            depositOk = true;
        } catch {
            depositOk = false;
        }

        // If amount is zero, the reference's assert in deposit would revert on certain overflow scenarios
        // but for non-zero amounts the deposit must succeed and record the funds so withdraw(amount) succeeds.
        // We restrict the property to amount > 0 to ensure it's within the admissible domain where reference guarantees strict increase.
        vm.assume(amount > 0);

        // Now attempt to withdraw the same amount; in the correct contract this must succeed (not revert).
        bool withdrawOk;
        vm.prank(actor);
        try c.withdraw(amount) {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // Single assertion: for all admissible inputs (nonzero actor and amount>0), withdraw must succeed after deposit
        assertTrue(withdrawOk);
    }
}

