pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz caller address and deposit amount. The property:
    // after deposit() completes, balances[caller] == old + amount
    // (the reference's assert prevents overflow/zero-acceptance issues that the mutant can allow).
    function testFuzz_property(address caller, uint256 amount) public {
        // Keep caller as non-zero to be a valid EOA; allow any amount (including 0)
        vm.assume(caller != address(0));

        // fund the caller so they can send `amount` wei; clamp large amounts to a reasonable upper bound
        uint256 maxFund = 1 ether;
        uint256 sendAmt = amount;
        if (sendAmt > maxFund) sendAmt = sendAmt % maxFund; // keep it wide but bounded

        vm.deal(caller, sendAmt);

        // record old balance stored in contract for caller via calling refund: but balances is private in C,
        // however mapping is not public so there's no getter. The contract C in this challenge has mapping as
        // `mapping(address => uint256) balances;` (no public getter). We therefore must observe behaviour via
        // sequence: deposit then attempt to withdraw that exact amount back — withdraw requires amount <= balances[msg.sender]
        // So to observe balances[caller], we use withdraw to transfer out known amounts. We'll capture behavior by:
        // 1) Have caller deposit amount
        // 2) Then attempt to withdraw exactly amount; it should succeed iff balances[caller] >= amount.
        // To make a universal property that the reference always satisfies and mutant sometimes breaks,
        // we assert that withdrawing the same `amount` that was just deposited succeeds.
        // The reference ensures balances[caller] increases by exactly msg.value, so withdraw(amount) must succeed.

        // Execute deposit as caller
        vm.prank(caller);
        // Call deposit with value sendAmt
        bool ok;
        try c.deposit{value: sendAmt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // If deposit revert occurred that would violate the reference behavior for admissible inputs.
        // We restrict to cases where deposit succeeded, because the reference should accept any payable call
        // (it only asserts overflow which can only fail on overflow scenarios; with our bounded funds, it won't overflow).
        // Ensure deposit succeeded — if it didn't, treat as failing the property by making assertion false.
        assertTrue(ok, "deposit call reverted");

        // Now try to withdraw exactly sendAmt as caller. For the correct contract, since balances[caller] increased by sendAmt,
        // withdraw(sendAmt) should succeed. We capture whether withdraw succeeded via try/catch.
        vm.prank(caller);
        bool withdrawOk;
        try c.withdraw(sendAmt) {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // The single assertion: for all admissible inputs (nonzero caller, bounded amount), the correct contract
        // will allow withdrawing exactly the amount just deposited; the mutant that accepts zero deposits or
        // that removes the assert can cause a scenario where deposit accepted zero or overflowed and withdraw fails.
        assertTrue(withdrawOk, "withdraw of deposited amount failed");
    }
}

